mySoln = "(4,5)";    %[control:editfield:6f7e]{"position":[10,17]} %[control:button:08fe]{"position":[20,21]}
if mySoln == "" %[output:group:73ac6b04]
    disp("Please enter a point.")
else
    ParseAndGiveFeedback(mySoln,pt) %[output:788fcca3]
end %[output:group:73ac6b04]
