%[text] c)
  %[control:button:614a]{"position":[1,2]}
% Plot the plane 2*x - 3*y = z
Exercise3cShape = true;
[x,y] = meshgrid(-2:0.1:2,-2:0.1:2); % Create a grid for x and y
z = 2*x - 3*y; % Calculate z based on the plane equation
surf(x,y,z,EdgeColor="none"); % Plot the surface %[output:7b7e3d86]
grid off %[output:7b7e3d86]
axis off %[output:7b7e3d86]
%%
cSoln = "Cartesian"; %[control:dropdown:6b45]{"position":[9,20]}
if exist("Exercise3cShape","var") %[output:group:2429606c]
