%[text] d) 
  %[control:button:9b80]{"position":[1,2]}
% Plot an ellipsoid with major radius 4 and minor radius 1
Exercise3dShape = true;
a = 4; % Major radius
b = 1; % Minor radius
[theta,phi] = meshgrid(linspace(0,2*pi,100),linspace(0,pi,100)); % Create a meshgrid for spherical coordinates

% Parametric equations for the ellipsoid
X = a * sin(phi) .* cos(theta);
Y = a * sin(phi) .* sin(theta);
Z = b * cos(phi);

% Plot the ellipsoid
figure; %[output:134c17b2]
surf(X,Y,Z,EdgeAlpha=0.4); % Plot the surface of the ellipsoid %[output:134c17b2]
grid off; % Turn on the grid %[output:134c17b2]
axis equal off; % Set equal scaling for all axes %[output:134c17b2]
%%
dSoln = "Spherical"; %[control:dropdown:776b]{"position":[9,20]}
if exist("Exercise3dShape","var") %[output:group:2dcea919]
    CheckExercise3(dSoln,"d") %[output:3fdd71b0] %[output:6c0d9c0e] %[output:2202b246] %[output:9222a49c] %[output:8772bb12]
else
    disp("You must plot the shape before you can answer.")
end %[output:group:2dcea919]
